/**
 * Phase 18 remediation — the ONE legitimate way to create the first
 * SUPER_ADMIN in a fresh deployment. Before this script, this
 * repository had no admin-bootstrap mechanism at all (a real, separate
 * finding from Phase 18's staging validation) — every prior staging/
 * test session could only reach a SUPER_ADMIN by hand-editing the
 * database directly.
 *
 * Deliberately NOT an HTTP endpoint: an ordinary authenticated user can
 * never reach this, by construction — it requires running a script with
 * direct database access (the same trust boundary as running
 * `prisma migrate deploy` itself), not a valid session token. This is
 * what makes it safe to also work in production, unlike
 * guard-destructive-migration.js's blanket production refusal — a real
 * production deployment genuinely needs to bootstrap its first admin
 * exactly once.
 *
 * Never creates a new account or password — it promotes an EXISTING
 * user who already registered through the real, real `POST
 * /auth/register` flow (so their password was chosen by them, through
 * the normal secure path, never hardcoded or generated by this script).
 *
 * Usage:
 *   BOOTSTRAP_SUPER_ADMIN_EMAIL=someone@example.com \
 *     node scripts/bootstrap-super-admin.js
 *
 * If a DIFFERENT user is already SUPER_ADMIN, this refuses by default —
 * re-running it can never silently elevate a second account. Pass
 * BOOTSTRAP_ALLOW_ADDITIONAL_SUPER_ADMIN=true to explicitly override
 * that (e.g. a deliberate, reviewed operational decision to add a
 * second super-admin) — never the default, always an explicit,
 * separate opt-in.
 *
 * Idempotent: re-running with the SAME email once that user is already
 * SUPER_ADMIN is a safe no-op (exit 0, nothing written).
 */
const { PrismaClient, UserRole, UserStatus, AuditActorType } = require("@prisma/client");

async function main() {
  const email = process.env.BOOTSTRAP_SUPER_ADMIN_EMAIL;
  if (!email) {
    console.error("REFUSING: BOOTSTRAP_SUPER_ADMIN_EMAIL is not set.");
    console.error("Usage: BOOTSTRAP_SUPER_ADMIN_EMAIL=someone@example.com node scripts/bootstrap-super-admin.js");
    console.error("The target user must already exist — register them first via the normal POST /auth/register flow.");
    process.exitCode = 1;
    return;
  }

  const allowAdditional = process.env.BOOTSTRAP_ALLOW_ADDITIONAL_SUPER_ADMIN === "true";
  const prisma = new PrismaClient();

  try {
    const target = await prisma.user.findUnique({ where: { email } });
    if (!target) {
      console.error(`REFUSING: no user found with email "${email}".`);
      console.error("Register this user first via the normal POST /auth/register flow, then re-run this script.");
      process.exitCode = 1;
      return;
    }

    if (target.role === UserRole.SUPER_ADMIN) {
      console.log(`Already SUPER_ADMIN: ${email} (id=${target.id}). Nothing to do.`);
      process.exitCode = 0;
      return;
    }

    const existingSuperAdmins = await prisma.user.count({ where: { role: UserRole.SUPER_ADMIN } });
    if (existingSuperAdmins > 0 && !allowAdditional) {
      console.error(
        `REFUSING: ${existingSuperAdmins} SUPER_ADMIN account(s) already exist, and "${email}" is not one of them.`,
      );
      console.error(
        "This script never silently elevates an additional account. If adding a second SUPER_ADMIN is a " +
          "deliberate, reviewed decision, re-run with BOOTSTRAP_ALLOW_ADDITIONAL_SUPER_ADMIN=true.",
      );
      process.exitCode = 1;
      return;
    }

    if (target.status === UserStatus.SUSPENDED) {
      console.error(`REFUSING: "${email}" is currently SUSPENDED. Resolve that separately before granting SUPER_ADMIN.`);
      process.exitCode = 1;
      return;
    }

    // A SUPER_ADMIN who can't actually pass RolesGuard (status !== ACTIVE)
    // would defeat the entire point of bootstrapping one — activated in
    // the same update, but only ever PENDING_VERIFICATION -> ACTIVE
    // (guarded above: never touches a SUSPENDED account).
    const updated = await prisma.user.update({
      where: { id: target.id },
      data: { role: UserRole.SUPER_ADMIN, status: UserStatus.ACTIVE },
    });

    await prisma.auditLog.create({
      data: {
        actorType: AuditActorType.SYSTEM,
        action: "user.super_admin_bootstrap",
        resourceType: "User",
        resourceId: target.id,
        before: { role: target.role, status: target.status },
        after: { role: updated.role, status: updated.status },
        reason: "scripts/bootstrap-super-admin.js",
      },
    });

    console.log(`Bootstrapped SUPER_ADMIN: ${email} (id=${target.id}). Status: ${updated.status}.`);
    process.exitCode = 0;
  } finally {
    await prisma.$disconnect();
  }
}

main().catch((error) => {
  console.error("Bootstrap script crashed:", error.message);
  process.exitCode = 1;
});
